package com.buildertoolbox.client.utils.world; import net.minecraft.client.MinecraftClient; import net.minecraft.block.*; import net.minecraft.util.Hand; import net.minecraft.util.hit.BlockHitResult; public final class BlockUtils {public static void interact(BlockHitResult hit,Hand hand,boolean swing){var mc=MinecraftClient.getInstance();if(mc.player!=null&&mc.interactionManager!=null){var result=mc.interactionManager.interactBlock(mc.player,hand,hit);if(swing&&result.isAccepted())mc.player.swingHand(hand);}} public static boolean isClickable(Block b){return b instanceof BlockWithEntity||b instanceof CraftingTableBlock||b instanceof AnvilBlock||b instanceof CartographyTableBlock||b instanceof SmithingTableBlock||b instanceof StonecutterBlock||b instanceof LoomBlock||b instanceof GrindstoneBlock||b instanceof BedBlock||b instanceof CakeBlock||b instanceof LeverBlock||b instanceof DoorBlock||b instanceof TrapdoorBlock||b instanceof FenceGateBlock||b instanceof ButtonBlock;} public static boolean isValidSpawnBlock(BlockState state){return !state.isAir()&&!state.isLiquid()&&!state.isReplaceable();} public static boolean isValidSpawnBlock(net.minecraft.util.math.BlockPos p){var w=MinecraftClient.getInstance().world;return w!=null&&w.getBlockState(p).isSolidBlock(w,p);} }